mapper.select:
SELECT ts.TEAM_ID, ts.SEASON, ts.CURRENT_RANK, ts.MATCHES_PLAYED, ts.WINS, ts.DRAWS, ts.LOSSES, ts.POINTS FROM TEAM_STATS ts WHERE ts.TEAM_ID = #{teamId}
AND ts.SEASON = #{season}
ORDER BY ts.SEASON DESC FETCH FIRST 1 ROWS ONLY

mapper.update:
UPDATE PREDICTIONS
SET IS_SUCCESS = #{isSuccess}
WHERE PREDICTION_ID = #{predictionId}
